import { describe, expect, it } from 'vitest';
import { applySmoothing, SMOOTHING_MODES, type SmoothingMode } from './smoothing';

const fixtureFrequencies = Array.from({ length: 161 }, (_, index) => 100 * Math.pow(100, index / 160));
const fixtureValues = fixtureFrequencies.map((_, index) => (
  index === 57 || index === 99 ? null : 7 * Math.sin(index * .37) + 3 * Math.cos(index * .11) - index * .015
));
const sampleIndices = [0, 20, 40, 80, 120, 160];

// Generated by ../Waveguide Generator/src/results/smoothing.js. These values
// lock every mode's v1 kernel (window, Gaussian weights, bandwidth schedule)
// for a quantity averaged as itself. The v1 psychoacoustic cubic mean of the
// raw values is retired: a cubic mean of signed dB was not REW's definition.
const v1Golden: Record<Exclude<SmoothingMode, 'psychoacoustic'>, Array<number | null>> = {
  none: [3, 4.225453318915351, 3.995765861691956, -10.424019178135264, 3.4572850088087037, 1.8432207990104366],
  '1/1': [5.7379094141307405, -1.346758499400347, -0.9941683997712195, -3.698708460141345, 0.4157711352646571, 0.6011403217205449],
  '1/2': [6.540749208771353, 1.6754792967476275, 1.7312530015245708, -7.477929994297836, 2.162890559200863, 3.2829544724533353],
  '1/3': [5.675529098841535, 2.916285125553419, 2.83456214197076, -8.921231026762685, 2.7999583551210914, 3.30206662181122],
  '1/6': [4.2337822807319, 3.8461839941667506, 3.6595979269855947, -9.990290109935426, 3.268065215284541, 2.6495017617979952],
  '1/12': [3.301392271668156, 4.136086384120905, 3.916567296323388, -10.321905971141835, 3.4127630352071736, 2.049147794918439],
  '1/24': [3, 4.225453318915351, 3.995765861691956, -10.424019178135264, 3.4572850088087037, 1.8432207990104366],
  '1/48': [3, 4.225453318915351, 3.995765861691956, -10.424019178135264, 3.4572850088087037, 1.8432207990104366],
  variable: [3, 4.225453318915351, 3.995765861691956, -10.321905971141835, 3.268065215284541, 3.30206662181122],
  erb: [6.442647917344022, 2.7549826998823286, 3.3004004180122326, -9.879154363105707, 3.031598332874172, 2.475680455064878],
};

const LINEAR_KERNEL_MODES = SMOOTHING_MODES.map(([mode]) => mode)
  .filter((mode): mode is Exclude<SmoothingMode, 'psychoacoustic'> => mode !== 'psychoacoustic');
const db = (value: number | null) => (value === null ? null : 10 * Math.log10(value));

describe('smoothing', () => {
  it.each(LINEAR_KERNEL_MODES)('keeps the v1 %s kernel for a linear quantity', (mode) => {
    const actual = sampleIndices.map((index) => applySmoothing(fixtureFrequencies, fixtureValues, mode, 'linear')[index]);
    actual.forEach((value, index) => {
      if (value === null) expect(value).toBe(v1Golden[mode][index]);
      else expect(value).toBeCloseTo(Number(v1Golden[mode][index]), 12);
    });
  });

  it.each(LINEAR_KERNEL_MODES)('averages %s levels as power, 10 log10 of the smoothed 10^(L/10)', (mode) => {
    const levels = fixtureValues.map((value) => (value === null ? null : value + 90));
    const power = levels.map((value) => (value === null ? null : 10 ** (value / 10)));
    const expected = applySmoothing(fixtureFrequencies, power, mode, 'linear').map(db);
    const actual = applySmoothing(fixtureFrequencies, levels, mode, 'level_db');
    actual.forEach((value, index) => {
      if (expected[index] === null) expect(value).toBeNull();
      else expect(value).toBeCloseTo(Number(expected[index]), 9);
    });
  });

  it('takes psychoacoustic levels as the cubic mean of power, not of dB', () => {
    const levels = fixtureValues;
    const cubedPower = levels.map((value) => (value === null ? null : 10 ** ((3 * value) / 10)));
    const expected = applySmoothing(fixtureFrequencies, cubedPower, 'psychoacoustic', 'linear')
      .map((value) => (value === null ? null : (10 / 3) * Math.log10(value)));
    const actual = applySmoothing(fixtureFrequencies, levels, 'psychoacoustic', 'level_db');
    actual.forEach((value, index) => {
      if (expected[index] === null) expect(value).toBeNull();
      else expect(value).toBeCloseTo(Number(expected[index]), 9);
    });
    // Peaks weigh more than dips: with the same window, the cubic mean of
    // power never falls below the plain mean of the dB values.
    const plainDb = applySmoothing(fixtureFrequencies, levels, 'psychoacoustic', 'linear');
    actual.forEach((value, index) => {
      if (value !== null) expect(value).toBeGreaterThanOrEqual(Number(plainDb[index]) - 1e-9);
    });
  });

  it.each(SMOOTHING_MODES)('leaves a constant level and a constant impedance unchanged in %s', (mode) => {
    const constant = fixtureFrequencies.map(() => 87.5);
    applySmoothing(fixtureFrequencies, constant, mode, 'level_db').forEach((value) => expect(value).toBeCloseTo(87.5, 9));
    applySmoothing(fixtureFrequencies, constant, mode, 'linear').forEach((value) => expect(value).toBeCloseTo(87.5, 9));
  });

  it('shifts with the level: smoothing L + c is smoothing L, plus c', () => {
    const shifted = fixtureValues.map((value) => (value === null ? null : value + 40));
    const base = applySmoothing(fixtureFrequencies, fixtureValues, 'psychoacoustic', 'level_db');
    applySmoothing(fixtureFrequencies, shifted, 'psychoacoustic', 'level_db').forEach((value, index) => {
      if (base[index] === null) expect(value).toBeNull();
      else expect(value).toBeCloseTo(Number(base[index]) + 40, 9);
    });
  });

  it('preserves the input reference for none and length mismatch', () => {
    expect(applySmoothing([100], fixtureValues, '1/3', 'level_db')).toBe(fixtureValues);
    expect(applySmoothing(fixtureFrequencies, fixtureValues, 'none', 'level_db')).toBe(fixtureValues);
  });
});
